style:
.ritual{--bg:#F3F2EE;--bg2:#E9E7E0;--ink:#1B1916;--ink2:#5D5850;--rule:#D3CFC5;--rubric:#9E1B14;--rubric2:#C7473C;--read:#8C1D18;--part:#D4776E;--hid:#CFC8BA;--img:#EFEBE2;--link:#1B1916}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .ritual{--bg:#15140F;--bg2:#1E1C16;--ink:#E6E1D6;--ink2:#A39C8F;--rule:#39352C;--rubric:#E4604B;--rubric2:#F0836F;--read:#E0553F;--part:#8C3A32;--hid:#3F3A31;--img:#26231D;--link:#E6E1D6}
}
:root[data-theme="dark"] .ritual{--bg:#15140F;--bg2:#1E1C16;--ink:#E6E1D6;--ink2:#A39C8F;--rule:#39352C;--rubric:#E4604B;--rubric2:#F0836F;--read:#E0553F;--part:#8C3A32;--hid:#3F3A31;--img:#26231D;--link:#E6E1D6}
.ritual *{box-sizing:border-box}
.ritual{margin:0;background:var(--bg);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.55;-webkit-font-smoothing:antialiased}
.ritual a{color:var(--link);text-decoration-color:var(--rule);text-underline-offset:3px}
.ritual a:hover{text-decoration-color:var(--rubric)}
.ritual a:focus-visible,.ritual summary:focus-visible{outline:2px solid var(--rubric);outline-offset:2px}
.ritual .wrap{display:grid;grid-template-columns:15rem minmax(0,1fr);gap:3rem;max-width:80rem;margin:0 auto;padding:2.5rem 2rem 6rem}
@media(max-width:60rem){.ritual .wrap{grid-template-columns:1fr;gap:1.5rem;padding:1.5rem 1rem 4rem}
.ritual .rail{position:static!important}
}
.ritual .rail{position:sticky;top:1.5rem;align-self:start;font-size:.9rem}
.ritual .rail .brand{font-family:var(--display);font-size:1.9rem;font-weight:600;line-height:1;margin:0 0 .25rem;color:var(--rubric)}
.ritual .rail .sub{margin:0 0 1.5rem;color:var(--ink2);font-size:.85rem}
.ritual .rail ol{list-style:none;margin:0;padding:0;border-top:1px solid var(--rule)}
.ritual .rail li{border-bottom:1px solid var(--rule)}
.ritual .rail li a{display:block;padding:.45rem 0;text-decoration:none}
.ritual .rail li a:hover{color:var(--rubric)}
.ritual .rail .key{margin-top:1.5rem;color:var(--ink2);font-size:.8rem;line-height:1.7}
.ritual .rail .key span{display:inline-block;width:.7rem;height:.7rem;border-radius:2px;vertical-align:-1px;margin-right:.35rem}
.ritual h1{font-family:var(--display);font-weight:500;font-size:clamp(2.4rem,5vw,3.6rem);line-height:1.02;margin:0 0 .5rem;text-wrap:balance}
.ritual h1 em{font-style:italic;color:var(--rubric)}
.ritual .lede{font-size:1.1rem;max-width:62ch;color:var(--ink);margin:0 0 1.75rem}
.ritual .eyebrow{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:var(--rubric);margin:0 0 .35rem}
.ritual .map{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;margin:0 0 1rem}
.ritual .map th,.ritual .map td{padding:.55rem .6rem;border-bottom:1px solid var(--rule);text-align:left;vertical-align:middle}
.ritual .map thead th{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.7rem;letter-spacing:.06em;text-transform:uppercase;color:var(--ink2);font-weight:500;border-bottom:1px solid var(--ink)}
.ritual .map tbody th{font-weight:600}
.ritual .map tbody th a{text-decoration:none}
.ritual .map .span{display:block;font-weight:400;font-size:.78rem;color:var(--ink2);font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
.ritual .map td.num{text-align:right;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.85rem}
.ritual .map td.barcell{width:26%;min-width:9rem}
.ritual .map tfoot td,.ritual .map tfoot th{border-top:1px solid var(--ink);border-bottom:0;font-weight:600}
.ritual .mapwrap{overflow-x:auto}
.ritual .bar{display:flex;height:10px;gap:2px;border-radius:2px;overflow:hidden}
.ritual .seg{display:block;height:100%}
.ritual .seg-readable{background:var(--read)}
.ritual .seg-partial{background:var(--part)}
.ritual .seg-hidden{background:var(--hid)}
.ritual .seg-images{background:var(--img)}
.ritual .method{font-size:.92rem;color:var(--ink2);max-width:68ch;margin:0 0 3rem}
.ritual .method p{margin:.4rem 0}
.ritual .trad{border-top:2px solid var(--rubric);padding-top:1.25rem;margin-top:3.5rem}
.ritual .trad h2{font-family:var(--display);font-weight:600;font-size:2rem;line-height:1.1;margin:0 0 .6rem;text-wrap:balance}
.ritual .counts{display:flex;flex-wrap:wrap;gap:.4rem 1.4rem;margin:0 0 .6rem;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.78rem;color:var(--ink2)}
.ritual .counts b{color:var(--ink);font-weight:500}
.ritual .trad-head .bar{max-width:30rem;margin-bottom:1.5rem}
.ritual .shape h3,.ritual .full h3{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;color:var(--rubric);font-weight:500;margin:1.4rem 0 .5rem}
.ritual .shape{max-width:72ch}
.ritual .shape p,.ritual .shape li{margin:.35rem 0}
.ritual .shape ol,.ritual .shape ul{padding-left:1.2rem}
.ritual details.full{margin-top:1.5rem;border:1px solid var(--rule);border-radius:3px;background:var(--bg2)}
.ritual details.full>summary{cursor:pointer;padding:.7rem 1rem;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.8rem;letter-spacing:.04em;list-style:none}
.ritual details.full>summary::before{content:'+ ';color:var(--rubric)}
.ritual details.full[open]>summary::before{content:'− '}
.ritual details.full>summary::-webkit-details-marker{display:none}
.ritual .note{padding:0 1rem;font-size:.85rem;color:var(--ink2)}
.ritual .note code{font-size:.8em}
.ritual .report{padding:.25rem 1rem 1rem;font-size:.92rem;overflow-x:auto}
.ritual .report h2{font-family:var(--display);font-size:1.5rem;font-weight:600;margin:1.6rem 0 .4rem;border-bottom:1px solid var(--rule);padding-bottom:.2rem}
.ritual .report h3{font-family:Spectral,Georgia,serif;font-size:1.05rem;font-weight:600;letter-spacing:0;text-transform:none;color:var(--ink);margin:1.1rem 0 .3rem}
.ritual .report h4{font-size:.95rem;margin:.9rem 0 .2rem}
.ritual .report ul,.ritual .report ol{padding-left:1.2rem}
.ritual .report li{margin:.2rem 0}
.ritual .report p{margin:.4rem 0}
.ritual .report table{border-collapse:collapse;font-size:.85rem;margin:.6rem 0}
.ritual .report th,.ritual .report td{border:1px solid var(--rule);padding:.3rem .5rem;text-align:left;vertical-align:top}
.ritual .report code,.ritual .note code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.82em;background:var(--bg);padding:.05em .3em;border-radius:2px}
.ritual .report hr{border:0;border-top:1px solid var(--rule);margin:1rem 0}
.ritual a.bk{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.78em;text-decoration:none;white-space:nowrap;padding:.05em .35em .05em .25em;border:1px solid var(--rule);border-radius:2px;background:var(--bg);color:var(--ink)}
.ritual a.bk:hover{border-color:var(--rubric)}
.ritual a.bk .dot{display:inline-block;width:.5em;height:.5em;border-radius:50%;margin-right:.3em;vertical-align:1px}
.ritual .st-readable .dot{background:var(--read)}
.ritual .st-partial .dot{background:var(--part)}
.ritual .st-hidden .dot{background:var(--hid);outline:1px solid var(--ink2)}
.ritual .st-images .dot{background:var(--img);outline:1px solid var(--ink2)}
.ritual .proposal{margin-top:4rem;border-top:2px solid var(--rubric);padding-top:1.25rem;max-width:72ch}
.ritual .proposal h2{font-family:var(--display);font-weight:600;font-size:2rem;margin:0 0 .6rem}
.ritual .proposal ul{padding-left:1.2rem}
@media (prefers-reduced-motion:reduce){.ritual *{scroll-behavior:auto}
}
